tasks.check:
set -o pipefail
cd /home/bcorfman/dev/freytag-forge
export PYTHONPATH=$PWD:$PWD/scripts/ringer/stage7:$PWD/scripts/ringer/phase1 TMPDIR=/tmp
PY=.venv/bin/python
D=data/stories/continuity-initiative
git diff --quiet -- storygame $D/plot.md || { echo "WHY: storygame or plot.md edited"; exit 1; }
awk '/^- id: SL-3C-H$/,/pressure_role/' $D/storylet-routes.yaml > /tmp/h.txt
grep -q "evacuation_window_missed" /tmp/h.txt || { echo "WHY: SL-3C-H lost its window condition"; exit 1; }
grep -q "truth_no_longer_containable\|rebecca_captured" /tmp/h.txt && { echo "WHY: SL-3C-H still requires the episode facts"; exit 1; }
grep -q "evacuation_recovery_ready" $D/knowledge.yaml $D/world.yaml $D/storylet-routes.yaml || { echo "WHY: recovery_ready fact not wired"; exit 1; }
grep -q "id: k_sl_3c_h_r1" $D/knowledge.yaml && { echo "WHY: action-earned recovery entry still present"; exit 1; }
$PY -c "from pathlib import Path; from storygame.story_package.loader import load_story_package as l; l(Path('$D'))" || { echo "WHY: package does not load"; exit 1; }
grep -n "RECOVERY_COMMAND" scripts/ringer/phase2/act3c_probe.py && { echo "WHY: stall still scripts a recovery command"; exit 1; }
$PY -m ruff format --check scripts/ringer/phase2 tests || { echo "WHY: not ruff-formatted"; exit 1; }
$PY -m ruff check scripts/ringer/phase2 tests/test_3c_finale_journey.py tests/test_act3c_probe.py || { echo "WHY: ruff check failed"; exit 1; }
for p in none clean costly stall; do O=$(mktemp -d); $PY scripts/ringer/phase2/act3c_probe.py --prefix $p --n 1 --out $O --dry-run || { echo "WHY: dry run failed for $p"; exit 1; }; $PY scripts/ringer/phase2/check_act3c_probe.py $O 1 --mode dry || { echo "WHY: probe check failed for $p"; exit 1; }; done
SUITES=""; for t in test_3c_finale_journey test_act3c_probe test_story_ending test_3c_cue_chain test_incident_loader test_incident_engine test_incident_recovery test_incident_handoff_guard test_leak_terms test_markdown_story_package test_package_audit test_scene_roleplay_contract test_disclosure_guards test_scene_relative_pacing test_spine_expected_reveals test_knowledge_leakage_matrix test_knowledge_projection test_loader_pacing_producers test_entry_variants test_3c_escape_result test_3c_surface_binding test_resolution_cascade test_canon_journey; do [ -f tests/$t.py ] && SUITES="$SUITES tests/$t.py"; done
$PY -m pytest -q -p no:cacheprovider $SUITES || { echo "WHY: suites failed"; exit 1; }
echo ok
